        var visits = (typeof currentUser !== 'undefined' && currentUser) ? currentUser.totalVisits || 0 : 0;
        
        // Admin Bypass Logic
        var _a = (typeof auth !== "undefined" && auth) ? auth.currentUser : null; var isAdmin = (_a && (_a.email || "") === "needcreations@gmail.com");

        var isFull = true;
