// ---- Spin Wheel Sound (Web Audio API — no external files needed) ----
window._spinSoundCtx = null;
window.playSpinTick = function() {
    if (localStorage.getItem('btc_audio') === 'false') return;
    if (document.hidden) return; // Don't play when minimized
    try {
        if (!window._spinSoundCtx) window._spinSoundCtx = new (window.AudioContext || window.webkitAudioContext)();
        var ctx = window._spinSoundCtx;
        var osc = ctx.createOscillator();
        var gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.frequency.value = 800 + Math.random() * 400;
        osc.type = 'triangle';
        gain.gain.value = 0.08;
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.08);
    } catch(e) {}
};

// =============================================
// Timechain TV Watch Time Tracker (Phil request 2026-04-13)
// This tracks minutes watched while the TV route is active and awards points / checks badges.
// =============================================
window._tctvTimer = null;
window._tctvMinutesSession = 0;
window._tctvStartTracker = function() {
    if (window._tctvTimer) return; // Already running
    window._tctvMinutesSession = 0; // Reset session count on re-entry
    // Mark for daily-challenge system (btc_tctv_visited)
    try { var _t = new Date().toISOString().split('T')[0]; localStorage.setItem('btc_tctv_visited_' + _t, 'true'); } catch(e) {}
    console.log('[TCTV] Watch tracker started.');

    window._tctvTimer = setInterval(function() {
        // Track the current route to ensure we only count when TCTV is actually active
        var id = (window.currentChannelId || '');
        if (id !== 'timechain-tv') {
            window._tctvStopTracker();
            return;
        }

        // Only track if tab is actually visible (don't farm points in background)
        if (document.hidden) return;

        // Increment total watch time (persisted to localStorage)
        var total = parseInt(localStorage.getItem('btc_tctv_watch_time') || '0') + 1;
        localStorage.setItem('btc_tctv_watch_time', total.toString());
        
        window._tctvMinutesSession++;
        // Daily challenge: persist daily TCTV minutes
        try { var _dt = new Date().toISOString().split('T')[0]; var _dm = parseInt(localStorage.getItem('btc_tctv_minutes_' + _dt) || '0') + 1; localStorage.setItem('btc_tctv_minutes_' + _dt, String(_dm)); } catch(e) {}
        console.log('[TCTV] Watch time:', total, 'min (Session:', window._tctvMinutesSession, 'min)');

        // Bump global community stats counter (one +1 per minute, non-anonymous only)
        try {
            if (typeof db !== 'undefined' && typeof firebase !== 'undefined'
                && typeof auth !== 'undefined' && auth.currentUser && !auth.currentUser.isAnonymous) {
                db.collection('stats').doc('global').set({
                    watchTimeMinutes: firebase.firestore.FieldValue.increment(1)
                }, { merge: true }).catch(function(){});
            }
        } catch(e) {}

        // Every 10 minutes (cumulative) award 10 points
        if (total % 10 === 0) {
            if (typeof awardPoints === 'function') {
                awardPoints(10, 'tctv_watch_10m'); // Use server-side action name
            }
            if (typeof checkBadges === 'function') {
                checkBadges();
            }
            if (typeof showToast === 'function') {
                showToast('👁️ +10 Points — Thanks for watching Timechain TV!');
            }
        } else if (total === 1) {
            // First minute toast
            if (typeof showToast === 'function') {
                showToast('📺 Watching Timechain TV — Points awarded every 10 min!');
            }
        }
    }, 60000); // 1 minute interval
};

window._tctvStopTracker = function() {
    if (window._tctvTimer) {
        clearInterval(window._tctvTimer);
        window._tctvTimer = null;
        console.log('[TCTV] Watch tracker stopped. Total minutes watched:', window._tctvMinutesSession);
    }
};


// =============================================
// AUDIT FIX: SEO & Dynamic Metadata (Phil request 2026-04-13)
// Updates canonical links, titles, and descriptions for better Google indexing.
// =============================================
window._updateSEO = function(id, title, desc) {
    if (!id) return;
    
    // 1. Update Title
    var baseTitle = 'Bitcoin Education Archive';
    document.title = (title ? title + ' | ' : '') + baseTitle;
    
    // 2. Update Canonical URL
    var canonical = document.querySelector('link[rel="canonical"]');
    if (canonical) {
        var path = (id === 'home' || id === '/') ? '' : '/app/' + id;
        canonical.setAttribute('href', 'https://bitcoineducation.quest' + path);
    }
    
    // 3. Update Meta Description
    var metaDesc = document.querySelector('meta[name="description"]');
    if (metaDesc && desc) {
        metaDesc.setAttribute('content', desc.substring(0, 160));
    }
    
    // 4. Update URL if not already correct (avoid loops)
    var targetUrl = window._cleanUrl(id);
    if (!window.location.href.includes(targetUrl)) {
        history.replaceState({ channel: id }, '', targetUrl);
    }
};

window.playSpinWin = function() {
    if (localStorage.getItem('btc_audio') === 'false') return;
    if (document.hidden) return;
    try {
        if (!window._spinSoundCtx) window._spinSoundCtx = new (window.AudioContext || window.webkitAudioContext)();
        var ctx = window._spinSoundCtx;
        [523, 659, 784, 1047].forEach(function(freq, i) {
            var osc = ctx.createOscillator();
            var gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.frequency.value = freq;
            osc.type = 'sine';
            gain.gain.value = 0.1;
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15 * (i + 1) + 0.3);
            osc.start(ctx.currentTime + 0.15 * i);
            osc.stop(ctx.currentTime + 0.15 * (i + 1) + 0.3);
        });
    } catch(e) {}
};

