// ---- Image Blur-Up Loading ----
// Adds a blurred placeholder while images load
(function() {
    var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) {
            m.addedNodes.forEach(function(node) {
                if (node.nodeType !== 1) return;
                var imgs = node.querySelectorAll ? [node, ...node.querySelectorAll('img.msg-img')] : [node];
                imgs.forEach(function(img) {
                    if (img.tagName !== 'IMG' || !img.classList.contains('msg-img') || img.dataset.blurUp) return;
                    img.dataset.blurUp = '1';
                    img.style.filter = 'blur(8px)';
                    img.style.transition = 'filter 0.4s ease';
                    if (img.complete && img.naturalWidth > 0) {
                        img.style.filter = 'none';
                    } else {
                        img.addEventListener('load', function() { img.style.filter = 'none'; }, { once: true });
                        img.addEventListener('error', function() { img.style.filter = 'none'; }, { once: true });
                    }
                });
            });
        });
    });
    if (document.getElementById('main')) {
        observer.observe(document.getElementById('main'), { childList: true, subtree: true });
    }
})();

// ---- Nacho Conversation Memory Across Sessions (#13) ----
// Persist last 20 exchanges to localStorage, load into AI context
(function() {
    var CONVO_KEY = 'btc_nacho_convo_persist';
    var MAX_PERSIST = 20;
    
    // Patch nachoRemember to also persist
    var _origRemember = window.nachoRemember;
    if (typeof _origRemember === 'function') {
        window.nachoRemember = function(q, a) {
            _origRemember(q, a);
            try {
                var stored = JSON.parse(localStorage.getItem(CONVO_KEY) || '[]');
                stored.push({ q: q, a: (a || '').substring(0, 200), t: Date.now() });
                if (stored.length > MAX_PERSIST) stored = stored.slice(-MAX_PERSIST);
                localStorage.setItem(CONVO_KEY, JSON.stringify(stored));
            } catch(e) {}
        };
    }
    
    // Restore on load into _nachoConvoHistory
    setTimeout(function() {
        if (typeof window._nachoConvoHistory !== 'undefined' && window._nachoConvoHistory.length === 0) {
            try {
                var stored = JSON.parse(localStorage.getItem(CONVO_KEY) || '[]');
                if (stored.length > 0) {
                    // Load last 5 into active history for AI context
                    for (var i = Math.max(0, stored.length - 5); i < stored.length; i++) {
                        window._nachoConvoHistory.push(stored[i]);
                    }
                }
            } catch(e) {}
        }
    }, 3000);
})();

// ---- Proactive Nacho Based on Reading (#14) ----
(function() {
    var READING_KEY = 'btc_nacho_topic_tracker';
    
    // Track topic categories when visiting channels
    var _origOnChannel = window.nachoOnPage;
    window.nachoOnPage = function(pageId) {
        if (typeof _origOnChannel === 'function') _origOnChannel(pageId);
        if (!pageId || typeof CHANNELS === 'undefined' || !CHANNELS[pageId]) return;
        try {
            var cat = CHANNELS[pageId].cat || '';
            var tracker = JSON.parse(localStorage.getItem(READING_KEY) || '{}');
            tracker[cat] = (tracker[cat] || 0) + 1;
            localStorage.setItem(READING_KEY, JSON.stringify(tracker));
            
            // After 3 visits to same category, proactive suggestion
            if (tracker[cat] === 3 && typeof forceShowBubble === 'function') {
                var catName = cat || 'this topic';
                setTimeout(function() {
                    forceShowBubble('You\'ve been reading a lot about ' + catName + '! 🦌 Want me to quiz you on it? Just say "quiz me on ' + catName + '" in Nacho Mode! ⚡');
                }, 5000);
            }
        } catch(e) {}
    };
})();

// ---- Reading Progress Per Channel (#15) ----
(function() {
    var PROGRESS_KEY = 'btc_channel_progress';
    var mainEl = document.getElementById('main');
    if (!mainEl) return;
    
    var _saveTimer = null;
    mainEl.addEventListener('scroll', function() {
        if (!window.currentChannelId) return;
        clearTimeout(_saveTimer);
        _saveTimer = setTimeout(function() {
            var scrollPct = mainEl.scrollHeight > mainEl.clientHeight ? Math.round(mainEl.scrollTop / (mainEl.scrollHeight - mainEl.clientHeight) * 100) : 100;
            try {
                var progress = JSON.parse(localStorage.getItem(PROGRESS_KEY) || '{}');
                var prev = progress[window.currentChannelId] || 0;
                if (scrollPct > prev) {
                    progress[window.currentChannelId] = scrollPct;
                    localStorage.setItem(PROGRESS_KEY, JSON.stringify(progress));
                }
            } catch(e) {}
        }, 500);
    }, { passive: true });
    
    // Show "Continue reading" indicator when revisiting
    window.getChannelProgress = function(channelId) {
        try {
            var progress = JSON.parse(localStorage.getItem(PROGRESS_KEY) || '{}');
            return progress[channelId] || 0;
        } catch(e) { return 0; }
    };
})();

// ---- Global Error Boundary (#16) ----
(function() {
    var _errorCount = 0;
    var _connToastShown = false;
    window.addEventListener('unhandledrejection', function(e) {
        _errorCount++;
        if (_errorCount > 10) return; // Don't spam
        var msg = e.reason && e.reason.message ? e.reason.message : '';
        var code = e.reason && e.reason.code ? e.reason.code : '';
        console.error('[Error Boundary] Unhandled promise rejection:', msg || e.reason);
        // Suppress permission-denied (normal during auth transitions) and missing index errors
        if (/permission.denied|Missing or insufficient|requires an index|PERMISSION_DENIED/i.test(msg + code)) return;
        // Show connection toast only once per session for real network errors
        if (!_connToastShown && /network|fetch|Failed to fetch|UNAVAILABLE|unavailable/i.test(msg + code)) {
            _connToastShown = true;
            if (typeof showToast === 'function') showToast('⚠️ Connection issue — some features may not work. Try refreshing.');
        }
    });
    
    window.addEventListener('error', function(e) {
        _errorCount++;
        if (_errorCount > 5) return;
        console.error('[Error Boundary]', e.message, e.filename, e.lineno);
    });
})();

// ---- Enhanced Offline Channel Caching (#17) ----
// Cache last 10 visited channel JSON files for offline reading
(function() {
    var OFFLINE_KEY = 'btc_offline_channels';
    var MAX_CACHED = 10;
    
    // After a channel loads, cache its data
    var _origGo = window.go;
    if (typeof _origGo === 'function' && !window._offlineCacheHooked) {
        window._offlineCacheHooked = true;
        // Use event-based approach instead of wrapping go()
        // Cache channel data when it loads successfully
        setInterval(function() {
            if (!window.currentChannelId || typeof CHANNELS === 'undefined') return;
            var ch = CHANNELS[window.currentChannelId];
            if (!ch || !ch.file) return;
            try {
                var cached = JSON.parse(localStorage.getItem(OFFLINE_KEY) || '{}');
                if (cached[window.currentChannelId] && Date.now() - cached[window.currentChannelId].ts < 86400000) return; // cached within 24h
                // Store channel JSON URL for SW to cache
                if ('caches' in window) {
                    caches.open('btc-offline-channels').then(function(cache) {
                        cache.add(ch.file).catch(function() {});
                    });
                }
                cached[window.currentChannelId] = { ts: Date.now() };
                // Keep only last 10
                var keys = Object.keys(cached);
                if (keys.length > MAX_CACHED) {
                    keys.sort(function(a, b) { return cached[a].ts - cached[b].ts; });
                    for (var i = 0; i < keys.length - MAX_CACHED; i++) {
                        delete cached[keys[i]];
                        if ('caches' in window) {
                            var file = CHANNELS[keys[i]] && CHANNELS[keys[i]].file;
                            if (file) caches.open('btc-offline-channels').then(function(c) { c.delete(file).catch(function() {}); });
                        }
                    }
                }
                localStorage.setItem(OFFLINE_KEY, JSON.stringify(cached));
            } catch(e) {}
        }, 10000); // Check every 10s
    }
})();

// ---- Onboarding Completion Tracking (#18) ----
(function() {
    // Track onboarding events anonymously
    var _origComplete = window._completeOnboarding;
    var _origSkip = window._onboardingSkip;
    
    function trackOnboarding(event, data) {
        if (typeof db === 'undefined' || typeof firebase === 'undefined') return;
        try {
            db.collection('stats').doc('onboarding').set({
                [event]: firebase.firestore.FieldValue.increment(1),
                lastUpdated: firebase.firestore.FieldValue.serverTimestamp()
            }, { merge: true }).catch(function() {});
        } catch(e) {}
    }
    
    // Track wizard shown
    var _origShow = window.showOnboardingWizard;
    if (typeof _origShow === 'function') {
        window.showOnboardingWizard = function() {
            var result = _origShow.apply(this, arguments);
            if (result) trackOnboarding('shown');
            return result;
        };
    }
    
    // Track completion via setOnboardingProfile
    var _origSetProfile = window.setOnboardingProfile;
    if (typeof _origSetProfile === 'function') {
        window.setOnboardingProfile = function(profile) {
            _origSetProfile.apply(this, arguments);
            if (profile && profile.level) {
                trackOnboarding('completed_' + profile.level);
                trackOnboarding('completed');
            }
        };
    }
})();


// Badge tooltip positioning — uses fixed positioning to avoid overflow clipping
(function() {
    function positionTip(item) {
        var tip = item.querySelector('.badge-tooltip');
        if (!tip) return;
        var rect = item.getBoundingClientRect();
        var tipW = 240;
        var left = rect.left + rect.width / 2 - tipW / 2;
        if (left < 8) left = 8;
        if (left + tipW > window.innerWidth - 8) left = window.innerWidth - tipW - 8;
        tip.style.left = left + 'px';
        tip.style.width = tipW + 'px';
        if (window.innerWidth > 900) {
            tip.style.top = (rect.top - 8) + 'px';
            tip.style.transform = 'translateY(-100%)';
        } else {
            tip.style.top = (rect.bottom + 8) + 'px';
            tip.style.transform = 'none';
        }
    }
    document.addEventListener('mouseover', function(e) {
        var item = e.target.closest('.badge-item');
        if (item) positionTip(item);
    });
    document.addEventListener('click', function(e) {
        var item = e.target.closest('.badge-item');
        if (item) positionTip(item);
    });
})();

// ---- Trail Channel Highlights ----
// Highlights sidebar channels that are part of the user's current active trail
(function() {
    'use strict';

    function getActiveTrail() {
        if (typeof window.NACHO_TRAILS === 'undefined') return null;
        var passed = [];
        try { passed = JSON.parse(localStorage.getItem('btc_trail_passed') || '[]'); } catch(e) {}
        var progress = {};
        try { progress = JSON.parse(localStorage.getItem('btc_trail_progress') || '{}'); } catch(e) {}

        for (var i = 0; i < window.NACHO_TRAILS.length; i++) {
            var trail = window.NACHO_TRAILS[i];
            // Skip if already passed
            if (passed.indexOf(trail.id) !== -1) continue;
            // Check if prerequisite is met
            if (trail.requires && passed.indexOf(trail.requires) === -1) break;
            // This is the active trail
            return { trail: trail, progress: progress[trail.id] || [] };
        }
        return null; // All trails complete
    }

    function highlightTrailChannels() {
        var active = getActiveTrail();
        // Clear all existing highlights first
        document.querySelectorAll('.ch-btn').forEach(function(btn) {
            btn.removeAttribute('data-trail');
            btn.style.removeProperty('border-left');
            btn.style.removeProperty('border-left-color');
            var dot = btn.querySelector('.trail-dot');
            if (dot) dot.remove();
        });

        if (!active) return;

        var trailChannelIds = active.trail.channels.map(function(c) { return c.id; });
        var visitedIds = active.progress;

        document.querySelectorAll('.ch-btn').forEach(function(btn) {
            // Extract channel ID from onclick
            var onclick = btn.getAttribute('onclick') || '';
            var match = onclick.match(/go\(['"]([^'"]+)['"]/);
            if (!match) return;
            var chId = match[1];

            var idx = trailChannelIds.indexOf(chId);
            if (idx === -1) return;

            var visited = visitedIds.indexOf(chId) !== -1;
            var color = active.trail.color || '#f7931a';

            btn.setAttribute('data-trail', active.trail.id);
            btn.style.borderLeft = '3px solid ' + (visited ? 'rgba(34,197,94,0.6)' : color);

            // Add trail indicator dot
            var dot = document.createElement('span');
            dot.className = 'trail-dot';
            dot.title = active.trail.emoji + ' ' + active.trail.name + (visited ? ' ✓' : ' — ' + active.trail.channels[idx].why);
            dot.style.cssText = 'display:inline-block;width:8px;height:8px;border-radius:50%;margin-left:auto;flex-shrink:0;background:' + (visited ? '#22c55e' : color) + ';box-shadow:0 0 4px ' + (visited ? 'rgba(34,197,94,0.5)' : color.replace(')', ',0.5)').replace('rgb', 'rgba')) + ';';
            if (visited) dot.textContent = '';
            btn.style.display = 'flex';
            btn.style.alignItems = 'center';
            btn.appendChild(dot);
        });
    }

    // Run on load and periodically (trail progress can change mid-session)
    function init() {
        if (typeof window.NACHO_TRAILS === 'undefined') {
            setTimeout(init, 2000);
            return;
        }
        highlightTrailChannels();
        // Re-highlight when user navigates home
        var _origGoHome = window.goHome;
        if (_origGoHome) {
            window.goHome = function() {
                _origGoHome.apply(this, arguments);
                setTimeout(highlightTrailChannels, 500);
            };
        }
        // Also re-highlight after channel visits (trail progress may update)
        var _origGo = window.go;
        if (_origGo) {
            window.go = function() {
                var result = _origGo.apply(this, arguments);
                // Re-highlight after navigation settles
                setTimeout(highlightTrailChannels, 1000);
                return result;
            };
        }
    }

    window.highlightTrailChannels = highlightTrailChannels;
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { setTimeout(init, 1500); });
    } else {
        setTimeout(init, 1500);
    }
})();

// ---- PVP Answer: Server-Side Validation Override ----
// Routes pvpAnswer through Cloud Function instead of direct Firestore write
(function() {
    'use strict';
    var _origPvpAnswer = null;
    function patchPvpAnswer() {
        if (typeof window.pvpAnswer !== 'function') return;
        if (window._pvpAnswerPatched) return;
        window._pvpAnswerPatched = true;
        _origPvpAnswer = window.pvpAnswer;

        window.pvpAnswer = function(questionIdx, answerIdx, btnEl) {
            // Still do the UI updates from original (disable buttons, show colors)
            var t = window._pvpState || {};
            if (t.answered) return;
            t.answered = true;
            if (t._questionTimeout) { clearTimeout(t._questionTimeout); t._questionTimeout = null; }

            // UI feedback
            var questions = t.questions || [];
            var q = questions[questionIdx];
            if (q && btnEl) {
                var opts = btnEl.parentElement;
                if (opts) {
                    var btns = opts.querySelectorAll('button');
                    for (var i = 0; i < btns.length; i++) {
                        btns[i].disabled = true;
                        btns[i].style.cursor = 'default';
                        btns[i].style.opacity = '0.7';
                    }
                    if (btns[q.correct]) {
                        btns[q.correct].style.borderColor = '#22c55e';
                        btns[q.correct].style.background = 'rgba(34,197,94,0.15)';
                        btns[q.correct].style.opacity = '1';
                    }
                    if (answerIdx >= 0 && answerIdx !== q.correct && btns[answerIdx]) {
                        btns[answerIdx].style.borderColor = '#ef4444';
                        btns[answerIdx].style.background = 'rgba(239,68,68,0.15)';
                    }
                }
                if (opts) opts.insertAdjacentHTML('afterend', '<div style="text-align:center;margin-top:12px;color:var(--text-muted);font-size:0.8rem;">' + (answerIdx === q.correct ? '✅ Correct! Waiting...' : answerIdx < 0 ? '⏰ Time\'s up!' : '❌ Wrong! Waiting...') + '</div>');
            }

            // Submit via Cloud Function
            if (typeof firebase !== 'undefined' && firebase.functions && t.matchId) {
                firebase.functions().httpsCallable('pvpSubmitAnswer')({
                    matchId: t.matchId,
                    questionIndex: questionIdx,
                    answerIndex: answerIdx
                }).then(function(result) {
                    if (result.data && result.data.alreadyAnswered) {
                        console.log('[PVP] Already answered, idempotent');
                    }
                }).catch(function(err) {
                    console.error('[PVP] Server answer submission failed:', err);
                    if (typeof showToast === 'function') showToast('⚠️ Answer submit failed — check connection');
                });
            }
        };
    }

    // Patch after PVP loads
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { setTimeout(patchPvpAnswer, 3000); });
    } else {
        setTimeout(patchPvpAnswer, 3000);
    }
    // Also re-patch on enterPVPMode — retry until pvp.js loads
    var _origEnterPVP = null;
    var _pvpPatchAttempts = 0;
    function _tryPatchEnterPVP() {
        if (window._pvpEnterPatched) return;
        if (typeof window.enterPVPMode === 'function') {
            window._pvpEnterPatched = true;
            _origEnterPVP = window.enterPVPMode;
            window.enterPVPMode = function() {
                _origEnterPVP.apply(this, arguments);
                setTimeout(patchPvpAnswer, 500);
                // Announce PVP lobby entry in Global Chat
                var _pvpName = (typeof currentUser !== 'undefined' && currentUser && currentUser.username) ? currentUser.username : null;
                if (_pvpName && typeof window.nachoGlobalAnnounce === 'function') {
                    window.nachoGlobalAnnounce('\u2694\uFE0F @' + _pvpName + ' just entered the PVP arena! Think you can beat them? \u27A1\uFE0F [Enter PVP Lobby](#pvp)');
                }
            };
        } else if (_pvpPatchAttempts < 20) {
            _pvpPatchAttempts++;
            setTimeout(_tryPatchEnterPVP, 2000);
        }
    }
    setTimeout(_tryPatchEnterPVP, 3000);
})();

// ---- Sidebar Reading Progress Indicators ----
(function() {
    // Add subtle progress bars to sidebar channel buttons
    // Runs after channels render and on navigation
    
    function updateSidebarProgress() {
        try {
            var progress = JSON.parse(localStorage.getItem('btc_channel_progress') || '{}');
            var buttons = document.querySelectorAll('.ch-btn');
            buttons.forEach(function(btn) {
                var onclick = btn.getAttribute('onclick') || '';
                var match = onclick.match(/go\('([^']+)'\)/);
                if (!match) return;
                var channelId = match[1];
                var pct = progress[channelId] || 0;
                
                // Remove existing progress bar if any
                var existing = btn.querySelector('.ch-progress');
                if (existing) existing.remove();
                
                if (pct > 0) {
                    var bar = document.createElement('div');
                    bar.className = 'ch-progress';
                    bar.style.cssText = 'position:absolute;bottom:0;left:0;height:2px;background:' + 
                        (pct >= 100 ? '#22c55e' : 'var(--accent,#f7931a)') + 
                        ';width:' + Math.min(pct, 100) + '%;border-radius:0 1px 0 0;transition:width 0.3s;opacity:0.7;';
                    btn.style.position = 'relative';
                    btn.style.overflow = 'hidden';
                    btn.appendChild(bar);
                    
                    // Add checkmark for 100%
                    if (pct >= 100 && !btn.querySelector('.ch-done')) {
                        var check = document.createElement('span');
                        check.className = 'ch-done';
                        check.style.cssText = 'position:absolute;right:6px;top:50%;transform:translateY(-50%);font-size:0.6rem;opacity:0.5;';
                        check.textContent = '\u2713';
                        btn.appendChild(check);
                    }
                }
            });
        } catch(e) {}
    }
    
    // Run on initial load
    setTimeout(updateSidebarProgress, 2000);
    
    // Re-run when navigating home or after channel loads
    var _origGoHome = window.goHome;
    if (_origGoHome) {
        window.goHome = function() {
            var result = _origGoHome.apply(this, arguments);
            setTimeout(updateSidebarProgress, 500);
            return result;
        };
    }
    
    // Also update after each channel visit
    var _origGoProg = window.go;
    if (_origGoProg) {
        window.go = function() {
            var result = _origGoProg.apply(this, arguments);
            setTimeout(updateSidebarProgress, 1000);
            return result;
        };
    }
    
    // Expose for manual refresh
    window.updateSidebarProgress = updateSidebarProgress;
})();
